<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { AlertOctagon, AlertTriangle, BellRing, Check, CheckCheck, ChevronRight, Clock3, Download, Info, RefreshCw, Search, ShieldAlert } from 'lucide-vue-next'
import PageHeader from '../components/common/PageHeader.vue'
import StatePanel from '../components/common/StatePanel.vue'
import StatusBadge from '../components/common/StatusBadge.vue'
import AppModal from '../components/common/AppModal.vue'
import { api } from '../api'
import { asApiError, type ApiError } from '../api/errors'
import type { Alert } from '../types/api'
import { useFleetStore } from '../stores/fleet'
import { useAuthStore } from '../stores/auth'
import { useUiStore } from '../stores/ui'
import { useOnline } from '../composables/useOnline'
import { canControlVehicle } from '../utils/permissions'
import { formatTime, relativeTime, shortVin } from '../utils/format'
const fleet = useFleetStore(), auth = useAuthStore(), ui = useUiStore(), router = useRouter()
const { online } = useOnline()
const search = ref(''), status = ref('open'), severity = ref('all'), loading = ref(false), error = ref<ApiError|null>(null)
const selected = ref<Alert>(), ackOpen = ref(false), note = ref(''), acknowledging = ref(false)
const filtered = computed(() => fleet.alerts.filter(a => (!status.value || a.status===status.value) && (severity.value==='all'||a.severity===severity.value) && `${a.title}${a.code}${a.vin}`.toLowerCase().includes(search.value.toLowerCase())).sort((a,b)=>b.occurred_at_ms-a.occurred_at_ms))
const criticalCount = computed(() => fleet.alerts.filter(a=>a.status==='open'&&a.severity==='critical').length)
const warningCount = computed(() => fleet.alerts.filter(a=>a.status==='open'&&a.severity==='warning').length)
const acknowledgedCount = computed(() => fleet.alerts.filter(a=>a.status==='acknowledged').length)
async function load() { loading.value=true;error.value=null;try{fleet.alerts=(await api.listAlerts()).items}catch(cause){error.value=asApiError(cause)}finally{loading.value=false} }
function canAcknowledge(alert: Alert) { return canControlVehicle(auth.user, fleet.vehicles.find(v => v.vin === alert.vin) || null) }
function openAck(alert: Alert) { selected.value=alert;note.value='';ackOpen.value=true }
async function acknowledge() {
  if(!selected.value)return
  acknowledging.value=true
  try{const result=await api.acknowledgeAlert(selected.value.id,note.value);fleet.upsertAlert(result);ackOpen.value=false;ui.toast('告警已确认','success','处理记录已写入审计事件')}catch(cause){ui.toast('确认失败','error',asApiError(cause).message)}finally{acknowledging.value=false}
}
function exportCsv(){const rows=['id,vin,code,title,severity,status,occurred_at',...filtered.value.map(a=>[a.id,a.vin,a.code,`"${a.title}"`,a.severity,a.status,new Date(a.occurred_at_ms).toISOString()].join(','))];const url=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv'}));const el=document.createElement('a');el.href=url;el.download='aurora-alerts.csv';el.click();URL.revokeObjectURL(url)}
</script>
<template>
  <div class="page alerts-page">
    <PageHeader eyebrow="ALERT OPERATIONS" title="告警中心" subtitle="集中处理车辆故障、连接与运营事件，确认动作将同步写入审计日志。"><template #actions><button class="btn btn-secondary" @click="exportCsv"><Download/>导出当前结果</button><button class="btn btn-primary" :disabled="loading" @click="load"><RefreshCw/>刷新告警</button></template></PageHeader>
    <div class="alert-metrics"><article class="card critical"><span><AlertOctagon/></span><div><small>严重告警</small><strong>{{ criticalCount }}</strong><p>需要立即关注</p></div></article><article class="card warning"><span><AlertTriangle/></span><div><small>一般警告</small><strong>{{ warningCount }}</strong><p>建议及时排查</p></div></article><article class="card info"><span><BellRing/></span><div><small>当前待处理</small><strong>{{ fleet.openAlerts.length }}</strong><p>全部授权车辆</p></div></article><article class="card resolved"><span><CheckCheck/></span><div><small>已确认</small><strong>{{ acknowledgedCount }}</strong><p>保留完整处理记录</p></div></article></div>
    <StatePanel :loading="loading" :error="error" :offline="!online&&!fleet.loaded" @retry="load">
      <section class="card alerts-card"><div class="alerts-toolbar"><div class="segmented"><button :class="{active:status==='open'}" @click="status='open'">待处理 <span>{{ fleet.openAlerts.length }}</span></button><button :class="{active:status==='acknowledged'}" @click="status='acknowledged'">已确认</button><button :class="{active:status===''}" @click="status=''">全部</button></div><div class="alert-filters"><div class="search-field"><Search/><input v-model="search" class="input" placeholder="搜索告警、VIN 或代码"></div><select v-model="severity" class="select severity-select"><option value="all">全部级别</option><option value="critical">严重</option><option value="warning">警告</option><option value="info">提示</option></select></div></div>
        <div v-if="filtered.length" class="alert-table"><div v-for="alert in filtered" :key="alert.id" class="alert-row" :class="[alert.severity,{acknowledged:alert.status==='acknowledged'}]"><span class="severity-line"/><span class="alert-type-icon"><AlertOctagon v-if="alert.severity==='critical'"/><AlertTriangle v-else-if="alert.severity==='warning'"/><Info v-else/></span><div class="alert-main"><div><strong>{{ alert.title }}</strong><StatusBadge :status="alert.severity" :label="alert.severity==='critical'?'严重':alert.severity==='warning'?'警告':'提示'"/></div><p><span class="mono">{{ alert.code }}</span><i/>{{ shortVin(alert.vin) }}<i/><Clock3/>{{ relativeTime(alert.occurred_at_ms) }}</p><div v-if="alert.status==='acknowledged'" class="ack-note"><Check/>{{ alert.acknowledgement_note||'已确认，无备注' }} · {{ formatTime(alert.acknowledged_at_ms,true) }}</div></div><div class="alert-time"><span>{{ formatTime(alert.occurred_at_ms,true) }}</span><small>{{ alert.status==='open'?'等待处理':'处理完成' }}</small></div><div class="alert-actions"><button class="btn btn-ghost btn-sm" @click="router.push(`/vehicles/${alert.vin}`)">车辆详情<ChevronRight/></button><button v-if="alert.status==='open'" class="btn btn-secondary btn-sm" :disabled="!canAcknowledge(alert)" :title="!canAcknowledge(alert)?'当前车辆角色无告警确认权限':''" @click="openAck(alert)"><Check/>确认处理</button></div></div></div>
        <StatePanel v-else :empty="true" :title="status==='open'?'没有待处理告警':'没有匹配的告警'" description="当前筛选条件下没有记录。车辆新告警会实时出现在这里。"/>
      </section>
    </StatePanel>
    <AppModal :open="ackOpen" title="确认告警处理" eyebrow="ACKNOWLEDGE ALERT" :busy="acknowledging" @close="ackOpen=false"><div v-if="selected" class="ack-target"><span :class="selected.severity"><ShieldAlert/></span><div><strong>{{ selected.title }}</strong><small class="mono">{{ selected.code }} · {{ selected.vin }}</small></div></div><div class="field"><label for="ack-note">处理备注（可选）</label><textarea id="ack-note" v-model="note" class="textarea" maxlength="1000" placeholder="记录排查结果、通知情况或后续行动…"/></div><p class="ack-disclaimer">确认代表已知悉此事件，不会自动消除车辆故障。操作人、时间与备注将保留在审计记录中。</p><template #footer><button class="btn btn-secondary" @click="ackOpen=false">取消</button><button class="btn btn-primary" :disabled="acknowledging" @click="acknowledge"><span v-if="acknowledging" class="spinner"/><Check v-else/>确认告警</button></template></AppModal>
  </div>
</template>
<style scoped>
.alert-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-bottom:18px}.alert-metrics article{padding:17px 19px;display:flex;align-items:center;gap:13px}.alert-metrics article>span{width:39px;height:39px;border-radius:11px;background:var(--red-soft);color:var(--red);display:grid;place-items:center}.alert-metrics article.warning>span{background:var(--orange-soft);color:var(--orange)}.alert-metrics article.info>span{background:var(--primary-soft);color:var(--primary)}.alert-metrics article.resolved>span{background:var(--green-soft);color:var(--green)}.alert-metrics svg{width:18px}.alert-metrics article>div{display:grid;grid-template-columns:1fr auto;flex:1;align-items:center}.alert-metrics small{font-size:9px;color:var(--text-2)}.alert-metrics strong{grid-row:span 2;font-size:24px;grid-column:2}.alert-metrics p{font-size:8px;color:var(--muted);margin-top:4px}.alerts-toolbar{padding:17px 19px;display:flex;justify-content:space-between;gap:15px;border-bottom:1px solid var(--line)}.segmented span{margin-left:4px}.alert-filters{display:flex;gap:9px}.severity-select{width:120px}.alert-row{display:flex;align-items:center;gap:14px;padding:18px 20px;border-bottom:1px solid var(--line);position:relative;transition:background .15s}.alert-row:hover{background:var(--bg-soft)}.alert-row:last-child{border:0}.alert-row.acknowledged{opacity:.76}.severity-line{position:absolute;left:0;top:18px;bottom:18px;width:2px;background:var(--primary);border-radius:2px}.critical .severity-line{background:var(--red)}.warning .severity-line{background:var(--orange)}.alert-type-icon{width:38px;height:38px;border-radius:11px;background:var(--primary-soft);color:var(--primary);display:grid;place-items:center;flex:none}.critical .alert-type-icon{background:var(--red-soft);color:var(--red)}.warning .alert-type-icon{background:var(--orange-soft);color:var(--orange)}.alert-type-icon svg{width:17px}.alert-main{flex:1;min-width:0}.alert-main>div:first-child{display:flex;align-items:center;gap:9px}.alert-main strong{font-size:11px}.alert-main p{display:flex;align-items:center;gap:7px;font-size:8px;color:var(--muted);margin-top:7px}.alert-main p i{width:2px;height:2px;background:var(--muted);border-radius:50%}.alert-main p svg{width:10px}.ack-note{display:flex;align-items:center;gap:5px;color:var(--green);font-size:8px;margin-top:8px}.ack-note svg{width:11px}.alert-time{display:flex;flex-direction:column;gap:5px;min-width:105px}.alert-time span{font-size:9px;color:var(--text-2)}.alert-time small{font-size:8px;color:var(--muted)}.alert-actions{display:flex;gap:6px}.ack-target{display:flex;align-items:center;gap:11px;background:var(--surface-2);padding:12px;border-radius:10px;margin-bottom:16px}.ack-target>span{width:34px;height:34px;border-radius:9px;display:grid;place-items:center;background:var(--orange-soft);color:var(--orange)}.ack-target>span.critical{background:var(--red-soft);color:var(--red)}.ack-target svg{width:16px}.ack-target>div{display:flex;flex-direction:column;gap:5px}.ack-target strong{font-size:11px;color:var(--text)}.ack-target small{font-size:8px;color:var(--muted)}.ack-disclaimer{font-size:9px;color:var(--muted);margin-top:12px}.alerts-card>.state-panel{min-height:320px}
@media(max-width:1100px){.alert-metrics{grid-template-columns:1fr 1fr}.alerts-toolbar{flex-direction:column}.alert-time{display:none}}
@media(max-width:750px){.alert-row{flex-wrap:wrap}.alert-main{min-width:65%}.alert-actions{margin-left:52px}.alert-filters{flex-direction:column}.severity-select{width:100%}}
</style>
